// dataset.js — measurement dataset model (Phase 3 §2, §3).
//
// A measurement dataset is the unit of experimental evidence. It carries its
// own provenance, instrument records, uncertainty metadata, and a SHA-256
// checksum of the raw source text. Datasets are immutable: every derived
// object is a new frozen object with a recorded transformation chain.
//
// Origin trust classification (Phase 3 §3) — CLOSED SET:
//   real-measurement      actual physical acquisition
//   synthetic-test-fixture  generated by software for testing ONLY
//   analytical-reference  computed from a closed-form solution
//   numerical-reference   computed by an independent numerical engine
//   unknown-origin        no trustworthy provenance recorded
//
// TRUST GATE: only `real-measurement` datasets can ever support a
// physical-validation claim. Everything else is software evidence.

import { createHash } from 'node:crypto';

export const DATASET_FORMAT = 'invention-lab/measurement-dataset/1';

export const ORIGINS = [
  'real-measurement',
  'synthetic-test-fixture',
  'analytical-reference',
  'numerical-reference',
  'unknown-origin',
];

/** Only this origin may ever unlock the physical-validation evidence stage. */
export const PHYSICAL_VALIDATION_ORIGIN = 'real-measurement';

export function sha256(text) {
  return createHash('sha256').update(text, 'utf8').digest('hex');
}

/**
 * Create a measurement dataset object.
 * meta: all Phase 3 §2 metadata fields. Unknown/absent fields must be
 * recorded as `null` — NEVER inferred or defaulted to a plausible value.
 */
export function createDataset(meta, samples, { rawSource = null } = {}) {
  const d = {
    format: DATASET_FORMAT,
    id: meta.id ?? null,
    version: meta.version ?? 1,
    origin: meta.origin ?? 'unknown-origin',
    // provenance
    source: {
      file: meta.source?.file ?? null,
      rawFileSha256: meta.source?.rawFileSha256 ?? null,
      datasetSha256: rawSource !== null ? sha256(rawSource) : (meta.source?.datasetSha256 ?? null),
      retrievedFrom: meta.source?.retrievedFrom ?? null,
      derivedFrom: meta.source?.derivedFrom ?? null,
      selfChecksum: meta.source?.selfChecksum ?? null,
    },
    experiment: {
      id: meta.experiment?.id ?? null,
      date: meta.experiment?.date ?? null,
      operator: meta.experiment?.operator ?? null,
    },
    specimen: {
      id: meta.specimen?.id ?? null,
      description: meta.specimen?.description ?? null,
    },
    configuration: meta.configuration ?? null,
    components: {
      nominal: meta.components?.nominal ?? null,
      independentlyMeasured: meta.components?.independentlyMeasured ?? null,
    },
    conditions: {
      operating: meta.conditions?.operating ?? null,
      environmental: meta.conditions?.environmental ?? null,
    },
    instruments: (meta.instruments ?? []).map((i) => ({
      manufacturer: i.manufacturer ?? null,
      model: i.model ?? null,
      serialNumber: i.serialNumber ?? null,
      resolution: i.resolution ?? null,
      uncertainty: i.uncertainty ?? null,
      calibration: i.calibration
        ? {
            certificateRef: i.calibration.certificateRef ?? null,
            status: i.calibration.status ?? 'unknown', // 'valid' | 'expired' | 'missing' | 'unknown'
            validUntil: i.calibration.validUntil ?? null,
          }
        : { certificateRef: null, status: 'missing', validUntil: null },
    })),
    quantities: meta.quantities ?? [], // [{ name, unit, direction, convention }]
    sampling: {
      frequencyHz: meta.sampling?.frequencyHz ?? null,
      timestamps: meta.sampling?.timestamps ?? 'relative-seconds',
      synchronization: meta.sampling?.synchronization ?? null,
    },
    replicates: meta.replicates ?? null, // [{ group, members }] or null
    uncertainty: meta.uncertainty ?? null, // declared measurement uncertainty
    corrections: meta.corrections ?? [], // known systematic corrections
    acquisition: {
      procedure: meta.acquisition?.procedure ?? null,
      reference: meta.acquisition?.reference ?? null,
    },
    license: meta.license ?? null,
    missingDataMarker: meta.missingDataMarker ?? null,
    samples: freezeSamples(samples ?? []),
    transformations: meta.transformations ?? [], // provenance chain of derived datasets
  };
  return Object.freeze(d);
}

function freezeSamples(samples) {
  return Object.freeze(samples.map((s) => Object.freeze({ ...s })));
}

/** Parse raw text as a dataset (JSON) and verify its checksum against itself. */
export function parseDataset(text) {
  let obj;
  try { obj = JSON.parse(text); } catch (e) {
    throw new Error(`dataset is not valid JSON: ${e.message}`);
  }
  if (obj.format !== DATASET_FORMAT) {
    throw new Error(`not an Invention Lab measurement dataset (format "${obj.format ?? 'missing'}")`);
  }
  const recorded = obj.source?.sha256 ?? null;
  const d = createDataset(obj, obj.samples ?? [], { rawSource: text });
  // artifact integrity: the SHA-256 of THIS dataset file is recorded so the
  // file can be re-verified later. source.sha256 refers to the ORIGINAL raw
  // instrument file and is verified via verifyChecksum against that file.
  const textSha256 = sha256(text);
  if (recorded && recorded === obj.source?.selfChecksum && obj.source?.selfChecksum !== textSha256) {
    throw new Error('dataset self-checksum mismatch — the dataset file was altered after its checksum was recorded');
  }
  return Object.freeze({ ...d, textSha256 });
}

/**
 * Verify the recorded source checksum against the ORIGINAL raw file text
 * (e.g. the instrument export). Throws when the raw file was altered.
 */
export function verifyChecksum(dataset, rawText) {
  const recorded = dataset.source?.rawFileSha256;
  if (!recorded) throw new Error('no source checksum recorded — provenance not verifiable');
  const computed = sha256(rawText);
  if (computed !== recorded) {
    throw new Error(`raw source checksum mismatch: recorded ${recorded.slice(0, 16)}…, computed ${computed.slice(0, 16)}… — the original file was altered`);
  }
  return true;
}

/**
 * Derive a new dataset from an existing one. The transformation is recorded
 * in the provenance chain; the parent dataset is never modified.
 */
export function deriveDataset(parent, transformation, newSamples, newMeta = {}) {
  if (!Object.isFrozen(parent)) throw new Error('deriveDataset: parent dataset is not frozen');
  const derived = createDataset({
    ...JSON.parse(JSON.stringify({ ...parent, samples: undefined, transformations: undefined })),
    ...newMeta,
    id: newMeta.id ?? `${parent.id}-derived`,
    version: (parent.version ?? 1) + 1,
    origin: parent.origin, // derived data INHERITS the parent's origin class
    source: { ...parent.source, derivedFrom: parent.id, transformation },
    transformations: [...(parent.transformations ?? []), { transformation, parentChecksum: parent.source.sha256 }],
  }, newSamples);
  return derived;
}

/**
 * TRUST GATE. Physical-validation evidence requires a dataset whose origin is
 * exactly 'real-measurement'. Synthetic, analytical, numerical, and unknown
 * origins are software evidence and can never unlock the physical stage.
 */
export function physicalValidationAllowed(dataset) {
  return dataset.origin === PHYSICAL_VALIDATION_ORIGIN;
}

/** CSV samples parser: header row names columns, rows become sample objects. */
export function parseSamplesCSV(text, { timeColumn = 't' } = {}) {
  const lines = text.split(/\r?\n/).filter((l) => l.trim() !== '');
  if (lines.length < 2) throw new Error('CSV samples: need a header row and at least one data row');
  const header = lines[0].split(',').map((h) => h.trim());
  if (!header.includes(timeColumn)) {
    throw new Error(`CSV samples: time column "${timeColumn}" not found in header [${header.join(', ')}]`);
  }
  const rows = [];
  for (const line of lines.slice(1)) {
    const cells = line.split(',').map((c) => c.trim());
    if (cells.length !== header.length) {
      throw new Error(`CSV samples: row "${line.slice(0, 60)}" has ${cells.length} cells, header has ${header.length}`);
    }
    const row = {};
    header.forEach((h, i) => {
      if (cells[i] === '') { row[h] = null; return; } // missing-data marker
      const n = Number(cells[i]);
      row[h] = Number.isNaN(n) ? cells[i] : n;
    });
    rows.push(row);
  }
  return rows;
}
